import pytest

from bedrock_protocol import v1001, v2168

VERSIONS = {"v1001": v1001, "v2168": v2168}

# generated by gophertunnel b8bd735:
# &packet.LabTable{ActionType: packet.LabTableActionReact, Position: protocol.BlockPos{1, -2, 300}, ReactionType: 12}
START_REACTION = bytes.fromhex("010203d8040c")

# generated by gophertunnel b8bd735:
# &packet.LabTable{ActionType: packet.LabTableActionReset, Position: protocol.BlockPos{0, 0, 0}, ReactionType: 0}
RESET = bytes.fromhex("0200000000")

GOLDENS = [
    pytest.param(
        version.LabTablePacket(
            type=version.LabTablePacket.Type.START_REACTION,
            pos=version.BlockPos(x=1, y=-2, z=300),
            reaction=version.LabTableReactionType.MISC_LARGE_SMOKE,
        ),
        START_REACTION,
        id=f"{name}-start-reaction",
    )
    for name, version in VERSIONS.items()
] + [
    pytest.param(
        version.LabTablePacket(
            type=version.LabTablePacket.Type.RESET,
            pos=version.BlockPos(x=0, y=0, z=0),
            reaction=version.LabTableReactionType.NONE,
        ),
        RESET,
        id=f"{name}-reset",
    )
    for name, version in VERSIONS.items()
]


@pytest.mark.parametrize("version", VERSIONS.values(), ids=VERSIONS.keys())
def test_lab_table_is_packet_109(version):
    assert version.PACKETS[109] is version.LabTablePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_lab_table_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_lab_table_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
